const cleanUid = u => String(u||'').toUpperCase().replace(/[^0-9A-F]/g,'');
const p = msg.payload || {};
const uid = cleanUid(p.uid);
const dev = String(p.dev||'').replace(/[^A-Za-z0-9_-]/g,'');
if (!uid || !dev) { node.warn('leitura invalida'); return null; }
const topicOut = 'presenca/' + dev + '/resultado';
const off = (p.off === 1 || p.off === true);   // leitura guardada offline e reenviada
const oid = Number(p.id);

// Reenvio offline: confirma (ACK) ao aparelho e ignora duplicatas (QoS 1
// pode entregar duas vezes, e o aparelho repete até receber o ACK).
let dup = false;
if (off) {
    if (!Number.isFinite(oid)) { node.warn('leitura offline sem id'); return null; }
    const vistos = flow.get('offids') || [];
    const chave = dev + ':' + oid;
    if (vistos.indexOf(chave) >= 0) { dup = true; }
    else { vistos.push(chave); if (vistos.length > 300) vistos.shift(); flow.set('offids', vistos); }
}
const ack = () => ({topic:topicOut, payload: JSON.stringify({status:'ACK', uid:uid, id:oid}), qos:1, retain:false});
if (dup) return ack();

const roster = flow.get('roster') || {};
const sess = flow.get('sessao') || {id:1, turma:'Aula 1'};
const agora = new Date().toISOString();
// Leitura offline: usa a hora original do aparelho, se ele a tinha (epoch em s).
const tsOk = off && Number.isFinite(Number(p.ts)) && Number(p.ts) > 1600000000;
const now = tsOk ? new Date(Number(p.ts) * 1000).toISOString() : agora;
let status, name = '';
if (roster[uid]) {
    status = 'OK'; name = roster[uid];
    const pres = flow.get('presencas') || [];
    if (!pres.some(r => r.sessao === sess.id && r.uid === uid)) {
        pres.push({t:now, uid:uid, name:name, dev:dev, sessao:sess.id, turma:sess.turma, off:off});
        flow.set('presencas', pres);
    }
} else {
    status = 'UNKNOWN';
    const pend = flow.get('pendentes') || {};
    if (!pend[uid]) pend[uid] = {t:now, dev:dev};
    flow.set('pendentes', pend);
}
const ev = flow.get('eventos') || [];
ev.unshift({t:agora, uid:uid, dev:dev, status:status, name:name, off:off});
ev.length = Math.min(ev.length, 50);
flow.set('eventos', ev);
if (off) return ack();
return {topic:topicOut, payload: JSON.stringify({status:status, uid:uid, nome:name}), qos:1, retain:false};

const dev = String(msg.topic).split('/')[1];
const d = flow.get('dispositivos') || {};
d[dev] = String(msg.payload);
flow.set('dispositivos', d);
return null;

const key = env.get('PANEL_KEY');
if (!key || !msg.req || msg.req.query.k !== key) {
    msg.statusCode = 403; msg.payload = 'acesso negado'; return [null, msg];
}
msg.statusCode = 200;
return [msg, null];

const key = env.get('PANEL_KEY');
if (!key || !msg.req || msg.req.query.k !== key) {
    msg.statusCode = 403; msg.payload = 'acesso negado'; return msg;
}
if (msg.statusCode === 403) return msg;
const sess = flow.get('sessao') || {id:1, turma:'Aula 1'};
const pres = (flow.get('presencas')||[]).filter(r => r.sessao === sess.id);
const pend = flow.get('pendentes') || {};
msg.payload = {
    sessao: sess,
    presentes: pres,
    matriculados: Object.keys(flow.get('roster')||{}).length,
    eventos: flow.get('eventos') || [],
    pendentes: Object.keys(pend).map(u => ({uid:u, t:pend[u].t, dev:pend[u].dev})),
    dispositivos: flow.get('dispositivos') || {}
};
msg.statusCode = 200;
return msg;

const cleanUid = u => String(u||'').toUpperCase().replace(/[^0-9A-F]/g,'');
const key = env.get('PANEL_KEY');
if (!key || !msg.req || msg.req.query.k !== key) {
    msg.statusCode = 403; msg.payload = 'acesso negado'; return msg;
}
if (msg.statusCode === 403) return msg;
const b = msg.payload || {};
const uid = cleanUid(b.uid);
const name = String(b.name||'').replace(/[;\r\n]/g,' ').trim().slice(0,39);
if (!uid || !name) { msg.statusCode = 400; msg.payload = {ok:false}; return msg; }
const roster = flow.get('roster') || {};
roster[uid] = name; flow.set('roster', roster);
const pend = flow.get('pendentes') || {};
const seen = pend[uid];
delete pend[uid]; flow.set('pendentes', pend);
if (seen) {
    const sess = flow.get('sessao') || {id:1, turma:'Aula 1'};
    const pres = flow.get('presencas') || [];
    if (!pres.some(r => r.sessao === sess.id && r.uid === uid)) {
        pres.push({t:seen.t, uid:uid, name:name, dev:seen.dev, sessao:sess.id, turma:sess.turma});
        flow.set('presencas', pres);
    }
}
msg.statusCode = 200; msg.payload = {ok:true};
return msg;

const cleanUid = u => String(u||'').toUpperCase().replace(/[^0-9A-F]/g,'');
const key = env.get('PANEL_KEY');
if (!key || !msg.req || msg.req.query.k !== key) {
    msg.statusCode = 403; msg.payload = 'acesso negado'; return msg;
}
if (msg.statusCode === 403) return msg;
const roster = flow.get('roster') || {};
let n = 0;
String((msg.payload||{}).texto||'').split(/\r?\n/).forEach(line => {
    const m = line.split(/[;,]/);
    const uid = cleanUid(m[0]);
    const name = String(m.slice(1).join(' ')||'').replace(/[;\r\n]/g,' ').trim().slice(0,39);
    if (uid && name) { roster[uid] = name; n++; }
});
flow.set('roster', roster);
msg.statusCode = 200; msg.payload = {ok:true, n:n};
return msg;

const key = env.get('PANEL_KEY');
if (!key || !msg.req || msg.req.query.k !== key) {
    msg.statusCode = 403; msg.payload = 'acesso negado'; return msg;
}
if (msg.statusCode === 403) return msg;
const old = flow.get('sessao') || {id:0, turma:'Aula 1'};
const turma = String((msg.payload||{}).turma||'').trim().slice(0,60) || ('Aula ' + (old.id+1));
flow.set('sessao', {id: old.id + 1, turma: turma});
msg.statusCode = 200; msg.payload = {ok:true};
return msg;

const key = env.get('PANEL_KEY');
if (!key || !msg.req || msg.req.query.k !== key) {
    msg.statusCode = 403; msg.payload = 'acesso negado'; return msg;
}
if (msg.statusCode === 403) return msg;
const q = s => '"' + String(s).replace(/"/g,'""') + '"';
const rows = ['data_hora_utc,sessao,turma,uid,nome,dispositivo'];
(flow.get('presencas')||[]).forEach(r => rows.push([r.t, r.sessao, q(r.turma), r.uid, q(r.name), r.dev].join(',')));
msg.payload = rows.join('\n');
msg.headers = {'Content-Type':'text/csv; charset=utf-8', 'Content-Disposition':'attachment; filename=presencas.csv'};
msg.statusCode = 200;
return msg;

const cleanUid = u => String(u||'').toUpperCase().replace(/[^0-9A-F]/g,'');
// Carrega a lista inicial de alunos da variável de ambiente ROSTER
// (linhas "UID;Nome"). Só preenche se a lista estiver vazia: a memória do
// servidor se perde quando ele reinicia ou "dorme", e isto a recompõe.
const roster = flow.get('roster') || {};
if (Object.keys(roster).length === 0) {
    let n = 0;
    String(env.get('ROSTER') || '').split(/\r?\n/).forEach(line => {
        const m = line.split(/[;,]/);
        const uid = cleanUid(m[0]);
        const name = String(m.slice(1).join(' ')||'').replace(/[;\r\n]/g,' ').trim().slice(0,39);
        if (uid && name) { roster[uid] = name; n++; }
    });
    flow.set('roster', roster);
    node.warn('Lista inicial carregada: ' + n + ' aluno(s)');
}
return null;
